// HasSession applies the HasEdge predicate on the "session" edge.
func HasSession() predicate.CreationImageJob {
	return predicate.CreationImageJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SessionTable, SessionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSessionWith applies the HasEdge predicate on the "session" edge with a given conditions (other predicates).
func HasSessionWith(preds ...predicate.CreationSession) predicate.CreationImageJob {
	return predicate.CreationImageJob(func(s *sql.Selector) {
		step := newSessionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CreationImageJob) predicate.CreationImageJob {
	return predicate.CreationImageJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CreationImageJob) predicate.CreationImageJob {
	return predicate.CreationImageJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CreationImageJob) predicate.CreationImageJob {
	return predicate.CreationImageJob(sql.NotPredicates(p))
}
